import {reports,explain,validateFile,ocrService,translationService,speechService,audioText} from './services.js';
const native=globalThis.HealthClearAndroid;
document.body.classList.toggle('android-app',!!native);
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=null,lang='en',page='upload',result=null,objectURL=null;
const notice='Fictional demo · Live OCR and AI explanations are not connected.';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500);}
function steps(n){return `<div class="steps" aria-label="Report progress">${['Upload report','Review text','Understand'].map((s,i)=>`${i?'<span class="rule"></span>':''}<span class="step ${i===n?'on':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;}
function language(){return `<label for="language">Explanation language</label><select id="language"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="hi" ${lang==='hi'?'selected':''}>हिन्दी · Hindi</option><option value="te" ${lang==='te'?'selected':''}>తెలుగు · Telugu</option></select>`;}
function bindLanguage(fn){$('#language').onchange=e=>{lang=e.target.value;speechService.stop();fn?.();};}
function clear(){native?.closeReport();speechService.stop();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;current=null;result=null;}
function render(route){page=route;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));if(route==='history')history();else if(route==='settings')settings();else upload();}
function upload(){page='upload';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='upload'));clear();$('#app').innerHTML=`<section class="intro"><div><div class="eyebrow">Clarity for your health journey</div><h1>Your medical report.<br><em>In words you understand.</em></h1><p>Make sense of medical terms, one report at a time. Get a simple explanation, in your language, at your pace.</p></div><div class="illustration" aria-hidden="true"><div class="paper"><b>+</b><i></i><i></i><i></i><span>✓</span></div></div></section>${steps(0)}<div class="workspace"><section class="card"><h2>Let’s start with your report</h2><p class="sub">Blood tests, written X-ray reports, and ultrasound reports.</p><div class="drop" id="drop"><div class="upload-icon" aria-hidden="true">↥</div><h3>Drop your report here</h3><p>Or choose a file from your device</p><div class="buttonrow"><button class="primary" id="choose">↥ &nbsp; Choose a file</button><button id="camera">▣ &nbsp; Use camera</button></div><div class="formats">JPG, PNG or PDF · Up to 10 MB</div><input hidden id="file" type="file" accept="image/jpeg,image/png,application/pdf"><input hidden id="capture" type="file" accept="image/jpeg,image/png" capture="environment"></div><div class="privacy-box"><span aria-hidden="true">♧</span><p><strong>Your report stays yours.</strong> This demo keeps personal files in local device memory (and temporary private cache on Android), until you leave the report or close it. Temporary cache is also cleared on the next app launch. No upload, training use, or automatic saving. <a href="#settings">Data & privacy details</a></p></div><label class="consent"><input type="checkbox" id="consent">I understand local processing and retention. Live OCR and explanations are unavailable for my own files.</label><p class="fine">Have a scan image? Please use the accompanying written report. HealthClear does not interpret medical images.</p><div id="error" role="alert"></div></section><aside class="card sample-card"><span class="tag">TAKE A LOOK AROUND</span><h2>A little curious?<br>Try a sample report.</h2><p>Explore how an explanation works before using a report of your own.</p><div class="sample-types"><button data-sample="blood">▤ &nbsp; Blood test <span>↗</span></button><button data-sample="xray">▧ &nbsp; Written X-ray report <span>↗</span></button><button data-sample="ultrasound">▥ &nbsp; Written ultrasound report <span>↗</span></button></div><p class="fine">FICTIONAL DEMO<br>Samples and explanations are prewritten examples, not real analysis or medical advice.</p></aside></div><section class="benefits"><div class="benefit"><span class="symbol">Aa</span><div><h3>Your language. Your pace.</h3><p>Read in English, Hindi, or Telugu.<br>Listen when that feels easier.</p></div></div><div class="benefit"><span class="symbol">≡</span><div><h3>Connected to the source</h3><p>See exactly where each finding<br>comes from in your report.</p></div></div><div class="benefit"><span class="symbol">♡</span><div><h3>A better doctor conversation</h3><p>Bring clearer questions and a<br>simple summary to your next visit.</p></div></div></section><div class="disclaimer">HealthClear helps you understand written reports. It does not diagnose conditions, prescribe treatment, or replace a healthcare professional’s assessment.</div>`;
$('#choose').onclick=()=>pick('file');$('#camera').onclick=()=>pick('capture');['file','capture'].forEach(id=>$('#'+id).onchange=e=>loadFile(e.target.files[0]));$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0]);};document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>sample(b.dataset.sample));}
function pick(id){if(!$('#consent').checked){toast('Please read and accept the processing notice first.');$('#consent').focus();return;}if(native){native.pickFile(id==='capture');return;}$('#'+id).click();}
function sample(id){clear();current={id,name:reports[id].name,text:reports[id].lines.join('\n'),demo:true};review();}
async function loadFile(file){if(!$('#consent')?.checked){toast('Please accept the processing notice before selecting a report.');return;}try{await validateFile(file);objectURL=URL.createObjectURL(file);current={name:file.name,type:file.type,demo:false,text:''};review(true);const extracted=await ocrService.extract(file);if(page==='review'){$('#ocr-status').textContent=extracted.message;$('#ocr-status').setAttribute('aria-busy','false');}}catch(e){$('#error').textContent=e.message;}}
function original(){if(native&&!current.demo&&current.type==='application/pdf')return `<div class="toolbar"><button id="pdf-prev">← Previous</button><span id="pdf-number"></span><button id="pdf-next">Next →</button></div><img id="pdf-page" alt="Original PDF page"><p class="fine">PDF pages are rendered on your device. Review all relevant pages.</p>`;if(current.demo)return `<div class="banner">Fictional sample · No patient data</div>${reports[current.id].lines.map((s,i)=>`<div id="source-${i}" tabindex="-1" class="source-line"><small>${String(i+1).padStart(2,'0')}</small> &nbsp;${esc(s)}</div>`).join('')}`;return current.type==='application/pdf'?`<object data="${objectURL}" type="application/pdf" aria-label="Original PDF"><a href="${objectURL}" target="_blank" rel="noopener">Open original PDF</a></object>`:`<img src="${objectURL}" alt="Uploaded report for manual review">`;}
function review(){page='review';$('#app').innerHTML=`<div class="eyebrow">Make sure the details are right</div><h1>Review before you continue.</h1>${steps(1)}<div class="banner" id="ocr-status" role="status" aria-busy="${!current.demo}">${current.demo?'Fictional demo · Sample text is prefilled; no OCR was performed.':'Checking file…'}</div><div class="workspace"><section class="card"><h2>Review the report text</h2><p class="sub">Never fill in a number you cannot read. Use [unreadable] and obtain a clearer copy instead.</p><label for="extracted">${current.demo?'Sample report text':'Manual transcription (OCR unavailable)'}</label><textarea id="extracted" spellcheck="false">${esc(current.text)}</textarea><div class="toolbar">${language()}</div><label class="consent"><input id="verified" type="checkbox">I checked all text, numbers, units, and uncertainty against the original.</label><div id="review-error" role="alert"></div><div class="toolbar"><button class="primary" id="continue">Explain this report →</button><button id="back">Back to upload</button></div><p class="fine">Only unchanged fictional samples can be explained in this demo. Real or edited reports require a configured server service.</p></section><aside class="card original"><h2>Original document</h2><p class="sub">${esc(current.name)}</p>${original()}</aside></div>`;bindLanguage();if(native&&!current.demo&&current.type==='application/pdf'){current.pdfPage=0;$('#pdf-prev').onclick=()=>native.pdfPage(current.pdfPage-1);$('#pdf-next').onclick=()=>native.pdfPage(current.pdfPage+1);native.pdfPage(0);}$('#back').onclick=upload;$('#extracted').oninput=()=>$('#verified').checked=false;$('#continue').onclick=()=>{const t=$('#extracted').value;const error=$('#review-error');if(!t.trim()||/\[unreadable\]|\?\?/.test(t)){error.textContent='Text is missing or unreadable. Use a clearer written report; do not guess.';return;}if(!$('#verified').checked){error.textContent='Please verify the text against the original first.';return;}try{result=explain(current.id,t,lang);current.text=t;results();}catch(e){error.textContent=e.message;}};}
function source(ref){return `<a href="#source-${ref}" data-source="${ref}" class="source-link">↗ ${esc(result.labels.source)} · ${ref+1}</a>`;}
function results(){page='results';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='upload'));result=translationService.get(current.id,current.text,lang);const e=result,l=e.labels;$('#app').innerHTML=`<div class="eyebrow">A clearer picture, one detail at a time</div><h1>Your report, made simpler.</h1>${steps(2)}<div class="banner">${notice} This explanation is prewritten educational content.</div><div class="toolbar">${language()}<button id="download">↓ Doctor-visit summary</button><button id="save">♡ Save sample to My Reports</button><button id="new">New report</button></div><p class="fine">No-save mode is the default. Saving stores only this fictional sample on this device.</p><div class="workspace"><section class="card"><div id="explanation" lang="${lang}"><h2>${l.summary}</h2><p>${esc(e.summary)}</p>${e.findings.map(f=>source(f.ref)).join(' ')}<h2 style="margin-top:25px">${l.finding}</h2>${e.findings.map(f=>`<div class="finding"><p>${esc(f.text)}</p>${f.value?`<p><strong>${esc(f.value)}</strong></p><p class="fine">Value · Reference range (exactly as printed)</p>`:''}${f.outside?`<span class="chip">↓ ${l.outside}</span><br>`:''}${source(f.ref)}</div>`).join('')}<div class="finding"><h3>${l.limits}</h3><p>${l.limit}</p></div><div class="finding"><h3>${l.terms}</h3><p>${e.terms}</p></div><div class="finding"><h3>${l.follow}</h3><p>${e.follow}</p>${source(e.followRef)}</div><div class="finding"><h3>${l.questions}</h3><p>${e.questions}</p></div><p>${l.context}</p></div><div class="audio"><p>AI-generated audio · Device text-to-speech reads the displayed explanation. Voice availability depends on your device. Android uses installed offline voices.</p><div class="buttonrow"><button id="play">▶ Play</button><button id="pause">Ⅱ Pause</button><button id="replay">↻ Replay</button><label>Speed <select id="speed"><option value="0.8">0.8×</option><option selected value="1">1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option></select></label></div><div id="audio-status" role="status"></div></div><h2>Ask about this report</h2><p class="sub">Demo answers use only this fictional sample. General chat is not connected.</p><div class="questions">${['What does this term mean?','Which results are outside the listed ranges?','What should I ask my doctor?','Does the report recommend a follow-up?'].map((q,i)=>`<button data-question="${i}">${q}</button>`).join('')}</div><form id="ask"><label for="question">Your question</label><div class="toolbar"><input id="question" type="text" maxlength="500" required placeholder="Ask about the written report"><button class="primary">Ask →</button></div></form><div id="answer" role="status"></div></section><aside class="card original"><h2>Original report</h2><p class="sub">${esc(current.name)} · Source text</p>${original()}</aside></div>`;
 bindLanguage(results);bindSources();$('#new').onclick=upload;$('#download').onclick=download;$('#save').onclick=save;$('#play').onclick=()=>play(false);$('#replay').onclick=()=>play(true);$('#pause').onclick=()=>{if(native)native.pause();else globalThis.speechSynthesis?.pause();$('#audio-status').textContent='Paused';};$('#speed').onchange=()=>{speechService.stop();$('#audio-status').textContent='Speed changed. Press Play to restart.';};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>answer(+b.dataset.question));$('#ask').onsubmit=ev=>{ev.preventDefault();$('#answer').className='answer';$('#answer').textContent='Free-text answers are unavailable in this demo. The report may not contain enough information to answer your question. Use a suggested question to explore the sample; ask a clinician about your own care.';};}
function bindSources(){document.querySelectorAll('[data-source]').forEach(a=>a.onclick=e=>{e.preventDefault();document.querySelectorAll('.highlight').forEach(x=>x.classList.remove('highlight'));const s=$('#source-'+a.dataset.source);s.classList.add('highlight');s.scrollIntoView({behavior:'smooth',block:'center'});s.focus({preventScroll:true});});}
function play(restart){try{if(native){native.speak(audioText(result),lang,+$('#speed').value,restart);return;}if(!restart&&globalThis.speechSynthesis?.paused){speechSynthesis.resume();$('#audio-status').textContent='Playing';return;}const u=speechService.play(audioText(result),lang,+$('#speed').value);$('#audio-status').textContent='Playing';u.onend=()=>{if($('#audio-status'))$('#audio-status').textContent='Finished';};u.onerror=()=>{if($('#audio-status'))$('#audio-status').textContent='Audio could not play. Please retry or read the text.';};}catch(e){$('#audio-status').textContent=e.message;}}
function answer(i){const e=result;let text='',ref=null;if(i===0)text=e.labels.terms+': '+e.terms;if(i===1){text=current.id==='blood'?e.findings[0].text+' '+e.findings[0].value:'No lab values or reference ranges are listed in this sample. This does not prove overall health.';ref=current.id==='blood'?1:0;}if(i===2)text=e.questions;if(i===3){text=e.follow;ref=e.followRef;}$('#answer').className='answer';$('#answer').innerHTML=`<div lang="${lang}">${esc(text)}</div>${ref!==null?source(ref):'<small>General education / suggested question</small>'}`;bindSources();}
function stored(){try{return JSON.parse(localStorage.getItem('healthclear-samples')||'[]').filter(x=>reports[x.id]&&['en','hi','te'].includes(x.lang));}catch{return [];}}
function save(){try{const items=stored();if(!items.some(x=>x.id===current.id&&x.lang===lang))items.push({id:current.id,lang,date:new Date().toISOString()});localStorage.setItem('healthclear-samples',JSON.stringify(items));toast('Fictional sample saved on this device. Delete it in My Reports.');}catch{toast('Browser storage is unavailable. Your report has not been saved.');}}
function history(){clear();const items=stored();$('#app').innerHTML=`<div class="eyebrow">Your space for clarity</div><h1>My Reports</h1><p>Only explicitly saved fictional samples appear here. Personal files are never saved in this demo.</p><section class="card">${items.length?items.map((r,i)=>`<div class="history-item"><div><strong>${reports[r.id].name}</strong><p class="fine">Fictional sample · ${r.lang.toUpperCase()}</p></div><div><button data-open="${i}">Open</button> <button data-delete="${i}">Delete</button></div></div>`).join(''):'<div class="empty"><div class="upload-icon">▤</div><h2>A fresh start.</h2><p>Your saved reports will appear here when you choose to save one.</p><a class="button primary" href="#upload">Explore a sample →</a></div>'}</section>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const r=items[+b.dataset.open];lang=r.lang;current={id:r.id,name:reports[r.id].name,text:reports[r.id].lines.join('\n'),demo:true};results();});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{try{items.splice(+b.dataset.delete,1);localStorage.setItem('healthclear-samples',JSON.stringify(items));history();toast('Saved sample deleted.');}catch{toast('Could not delete browser storage. Clear this site’s data in browser settings.');}});}
function settings(){clear();$('#app').innerHTML=`<div class="eyebrow">You are in control</div><h1>Settings & privacy</h1><section class="card developer-card" aria-labelledby="developer-heading"><div class="developer-avatar" aria-hidden="true">PB</div><div><span class="eyebrow">About the developer</span><h2 id="developer-heading">Punit Badyal</h2><p>Developer of HealthClear — helping people understand written medical reports in simple language.</p><a class="button" href="https://github.com/punitbadyal01-blip" rel="noopener noreferrer">View my GitHub ↗</a><p class="fine">GitHub · @punitbadyal01-blip</p></div></section><div class="workspace"><section class="card"><h2>Local, no-save by default</h2><p>Your selected file stays on your device. It is not sent to a server. Android keeps temporary PDF and camera files in private app cache for viewing. Leaving the report clears those files; after an interrupted session, the next launch clears them. The operating system controls memory reclamation.</p><p>Only fictional sample IDs and language choices can be explicitly saved in this device. Anyone using this device profile can see those samples. Personal medical uploads cannot be saved.</p><p>We do not collect uploads for training. There is no analytics, cloud history, sign-in, or account in this demo. No regulatory certification is claimed.</p><h2>Audio processing</h2><p>On Android, playback uses an installed offline text-to-speech voice. Install an English, Hindi, or Telugu voice in Android settings if one is missing. Only the displayed fictional explanation is spoken. Browser preview uses browser speech synthesis, which may use a network voice.</p><button id="erase">Delete all saved samples</button><p class="fine">Account deletion: not applicable. This version creates no accounts.</p></section><section class="card sample-card"><span class="tag">INTEGRATION STATUS</span><h2>What’s connected?</h2><p><strong>Working:</strong> file validation, local preview, manual text review, source links, three-language fictional explanations, device audio, sample history, and text-summary download.</p><p><strong>Not connected:</strong> OCR, live medical explanation, live translation, cloud storage, authentication, and account management.</p><p>For real uploads, text review is the final available step. A scan without a written report cannot be explained. Upload the accompanying written report.</p><a class="button" href="#upload">Back to upload →</a></section></div>`;$('#erase').onclick=()=>{try{localStorage.removeItem('healthclear-samples');toast('All saved samples deleted.');}catch{toast('Storage is unavailable. Clear this site’s data in browser settings.');}};}
function download(){const r=reports[current.id];const text='HEALTHCLEAR — FICTIONAL DEMO\nDoctor-visit discussion summary\nNot a diagnosis or treatment plan.\n\n'+audioText(result)+'\n\nSOURCE REPORT\n'+r.lines.map((s,i)=>`[${i+1}] ${s}`).join('\n')+'\n\nTRACEABILITY\nSummary → [2]\n'+result.findings.map(f=>`${f.text} → [${f.ref+1}]`).join('\n')+`\n${result.follow} → [${result.followRef+1}]\nDefinitions and doctor questions are general education.`;if(native){native.exportSummary(text);return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='HealthClear-fictional-doctor-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Fictional doctor-visit summary downloaded.');}
window.healthclearNativeError=toast;
window.healthclearAudioStatus=text=>{if($('#audio-status'))$('#audio-status').textContent=text;};
window.healthclearReceiveFile=(base64,name,type,pages)=>{const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));loadFile(new File([bytes],name,{type}));};
window.healthclearPdfPage=(url,index,count)=>{if(!$('#pdf-page'))return;current.pdfPage=index;$('#pdf-page').src=url;$('#pdf-number').textContent=`Page ${index+1} of ${count}`;$('#pdf-prev').disabled=index===0;$('#pdf-next').disabled=index===count-1;};
window.healthclearAndroidBack=()=>{if(page==='results')review();else if(page==='review')upload();else if(page!=='upload')location.hash='upload';else native?.finishApp();};
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');const route=a?.getAttribute('href')?.slice(1);if(['upload','history','settings'].includes(route)){e.preventDefault();window.history.replaceState(null,'','#'+route);render(route);}});
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));window.addEventListener('pagehide',clear);render(location.hash.slice(1)||'upload');
